<script lang="ts">import { onMount } from 'svelte'; let {data}=$props(); let code=$state('');let message=$state('');let attempt=$state<any>(null);let index=$state(0);let values=$state<Record<string,string>>({});let saving=$state('');let remaining=$state(0);let confirm=$state(false);let q=$derived(attempt?.questions[index]);
onMount(()=>{const id=setInterval(()=>{if(attempt){remaining=Math.max(0,new Date(attempt.expiresAt).getTime()-Date.now());if(!remaining)submit(true)}},1000);const handler=(e:PageTransitionEvent)=>{if(e.persisted) location.replace('/exam')};addEventListener('pageshow',handler);history.replaceState({examRoot:true},'', '/exam');const pop=()=>{location.replace('/exam')};addEventListener('popstate',pop);return()=>{clearInterval(id);removeEventListener('pageshow',handler);removeEventListener('popstate',pop)}});
const fmt=(ms:number)=>`${Math.floor(ms/60000)}`.padStart(2,'0')+':'+`${Math.floor(ms/1000)%60}`.padStart(2,'0');
async function start(){message='';const r=await fetch('/api/exam/start',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code})});const j=await r.json();if(!r.ok){message=j.message;return}attempt=j;values=Object.fromEntries(j.questions.map((q:any)=>[q.id,q.answer||'']));remaining=new Date(j.expiresAt).getTime()-Date.now()}
let timers:Record<string,ReturnType<typeof setTimeout>>={}; function save(qid:string){clearTimeout(timers[qid]);timers[qid]=setTimeout(async()=>{saving='저장 중...';const r=await fetch('/api/exam/answer',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({attemptQuestionId:qid,value:values[qid]})});saving=r.ok?'저장됨':'저장에 실패했습니다.'},500)}
async function submit(timeout=false){if(!attempt)return;const r=await fetch('/api/exam/submit',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({attemptId:attempt.id,timeout})});const j=await r.json();if(r.ok){attempt={...attempt,submittedAt:j.submittedAt};confirm=false}else message=j.message}
</script>
<main class="mx-auto min-h-screen max-w-6xl px-4 py-6">{#if !attempt}<section class="mx-auto mt-24 max-w-md card p-7"><h1 class="text-2xl font-bold">시험 코드 입력</h1><p class="mt-2 text-sm text-slate-500">발급받은 6자리 응시 코드를 입력해 주세요.</p><label class="label mt-6" for="code">응시 코드</label><input id="code" bind:value={code} maxlength="6" class="w-full uppercase tracking-[.35em]" placeholder="A7K3PX"/><button class="btn mt-4 w-full" onclick={start}>시험 시작</button>{#if message}<p class="mt-4 text-sm text-red-600">{message}</p>{/if}</section>{:else if attempt.submittedAt}<section class="mx-auto mt-24 max-w-md card p-8 text-center"><h1 class="text-2xl font-bold">제출이 완료되었습니다</h1><p class="mt-3 text-slate-600">답안이 안전하게 접수되었습니다. 결과는 운영진 채점 후 확인됩니다.</p><a href="/" class="btn mt-7 inline-block">메인으로</a></section>{:else}<header class="card flex items-center justify-between p-4"><div><b>OWKR 관리자 선발시험</b><span class="ml-3 text-sm text-slate-500">{index+1} / {attempt.questions.length}번 문제</span></div><div class="font-mono text-lg font-bold text-navy">남은 시간 {fmt(remaining)}</div></header><div class="mt-4 grid gap-4 lg:grid-cols-[180px_1fr]"><aside class="card p-3"><p class="mb-3 text-sm font-semibold">문제 목록</p><div class="grid grid-cols-5 gap-2">{#each attempt.questions as item,i}<button onclick={()=>index=i} class:!bg-navy={i===index} class:!text-white={i===index} class="h-8 rounded border border-line text-sm {values[item.id]?.trim()?'bg-sky-100':'bg-white'}">{i+1}</button>{/each}</div><button class="btn mt-6 w-full text-sm" onclick={()=>confirm=true}>시험 제출</button></aside>{#if q}<section class="card p-6"><p class="text-sm font-semibold text-sky-800">문제 {index+1} · {q.points}점</p><h1 class="mt-3 whitespace-pre-wrap text-xl leading-8">{q.content}</h1>{#if q.type==='multiple'}<div class="mt-7 space-y-3">{#each q.options as option,i}<label class="flex cursor-pointer items-center gap-3 rounded border border-line p-3 hover:bg-sky-50"><input type="radio" name={q.id} value={String(i)} bind:group={values[q.id]} onchange={()=>save(q.id)}/>{option}</label>{/each}</div>{:else}<textarea class="mt-7 min-h-40 w-full" bind:value={values[q.id]} oninput={()=>save(q.id)} placeholder={q.type==='short'?'답변을 입력해 주세요.':'답변을 충분히 작성해 주세요.'}></textarea>{/if}<div class="mt-6 flex items-center justify-between"><button class="btn-secondary" disabled={index===0} onclick={()=>index--}>이전 문제</button><span class="text-sm text-slate-500">{saving}</span><button class="btn-secondary" disabled={index===attempt.questions.length-1} onclick={()=>index++}>다음 문제</button></div></section>{/if}</div>{#if confirm}<div class="fixed inset-0 grid place-items-center bg-black/40 p-4"><div class="card w-full max-w-sm p-6"><h2 class="text-xl font-bold">시험을 제출하시겠습니까?</h2><p class="mt-3 text-slate-600">제출 후에는 답안을 수정하거나 다시 응시할 수 없습니다.<br/>미응답 문제: {attempt.questions.filter((item:any)=>!values[item.id]?.trim()).length}개</p><div class="mt-6 flex justify-end gap-2"><button class="btn-secondary" onclick={()=>confirm=false}>취소</button><button class="btn" onclick={()=>submit()}>제출</button></div></div></div>{/if}{/if}</main>
